"use client";

import { useEffect, useId, useRef, useState } from "react";

import { AlertTriangleIcon } from "@/components/blocks/parts/icons";
import { RollingText } from "@/components/blocks/parts/rolling-text";
import { SegmentedControl } from "@/components/motion/segmented-control";
import { Slider } from "@/components/motion/slider";
import { Switch } from "@/components/motion/switch";
import { Button } from "@/components/ui/button";

import { BlockFrame } from "../parts/block-frame";
import {
  CARDS,
  CREDIT_PRICE,
  CUSTOM,
  dailyRate,
  LOW_BALANCE,
  PACKS,
  START_BALANCE,
  type Threshold,
  THRESHOLDS,
  USAGE,
} from "./credit-topup/data";
import { Odometer } from "./credit-topup/odometer";
import { PackPicker } from "./credit-topup/pack-picker";
import { UsageBars } from "./credit-topup/usage-bars";
import { CardIcon, LoaderIcon } from "./shared/icons";
import { formatCents, formatCount } from "./shared/money";
import { Reveal } from "./shared/reveal";

const THRESHOLD_OPTIONS = THRESHOLDS.map((value) => ({
  value,
  label: formatCount(Number(value)),
}));

/**
 * Buys reminder credits for a Fernhill clinic. Read the balance, how long it
 * lasts and 14 days of use, pick a pack or a custom amount, set an automatic
 * top-up and buy. The balance then rolls up like an odometer. It is a demo:
 * it uses a placeholder saved card and charges nothing.
 */
export function CreditTopup({ className }: { className?: string }) {
  const titleId = useId();
  const packName = useId();
  const autoId = useId();
  const [balance, setBalance] = useState(START_BALANCE);
  const [amount, setAmount] = useState(PACKS[1]!.credits);
  const [packId, setPackId] = useState<string | null>(PACKS[1]!.id);
  const [auto, setAuto] = useState(false);
  const [threshold, setThreshold] = useState<Threshold>("250");
  const [card, setCard] = useState(0);
  const [buying, setBuying] = useState(false);
  const [notice, setNotice] = useState("");
  const timer = useRef<number | undefined>(undefined);
  useEffect(() => () => window.clearTimeout(timer.current), []);

  const pack = PACKS.find((item) => item.id === packId);
  const bonus = pack?.bonus ?? 0;
  const price = pack ? pack.price : amount * CREDIT_PRICE;
  const rate = dailyRate();
  const daysLeft = Math.floor(balance / rate);
  const low = balance < LOW_BALANCE;

  const choosePack = (id: string) => {
    const next = PACKS.find((item) => item.id === id);
    if (!next) return;
    setPackId(id);
    setAmount(next.credits);
  };

  const slide = (credits: number) => {
    setAmount(credits);
    setPackId(PACKS.find((item) => item.credits === credits)?.id ?? null);
  };

  const buy = () => {
    if (buying) return;
    setBuying(true);
    setNotice("");
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => {
      setBalance((value) => value + amount + bonus);
      setBuying(false);
      setNotice(
        `${formatCount(amount + bonus)} credits added. ${formatCents(price)} charged to ${CARDS[card]}.`,
      );
    }, 1200);
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <div className="grid gap-6 p-5 @2xl:p-8 @4xl:grid-cols-[1fr_1.1fr]">
        <div className="flex min-w-0 flex-col gap-5">
          <header className="flex flex-col gap-1">
            <h2 id={titleId} className="text-lg font-semibold">
              Reminder credits
            </h2>
            <p className="text-sm text-muted-foreground">
              Every text reminder to a patient uses one credit.
            </p>
          </header>

          <div className="flex flex-wrap items-end justify-between gap-3">
            <div>
              <p className="text-sm text-muted-foreground">Balance</p>
              <p className="flex items-baseline gap-2">
                <Odometer
                  value={balance}
                  className="text-4xl font-semibold tracking-tight"
                />
                <span className="text-sm text-muted-foreground">credits</span>
              </p>
            </div>
            {low ? (
              <span className="inline-flex items-center gap-1.5 rounded-full bg-marketing-amber-surface px-2.5 py-1 text-xs font-medium text-marketing-amber-ink">
                <AlertTriangleIcon aria-hidden="true" className="size-3.5" />
                Running low
              </span>
            ) : null}
          </div>
          <p className="text-sm">
            About{" "}
            <span className="font-semibold tabular-nums">
              {formatCount(daysLeft)} days
            </span>{" "}
            left at {formatCount(rate)} credits a day.
          </p>

          <UsageBars values={USAGE} />
        </div>

        <div className="flex min-w-0 flex-col gap-5">
          <PackPicker
            name={packName}
            value={packId}
            onValueChange={choosePack}
          />

          {/* The slider's thumb layer reaches past the track, so the clip keeps the card from scrolling sideways. */}
          <div className="-mx-3 overflow-x-clip px-3">
            <Slider
              label="Or set your own amount"
              min={CUSTOM.min}
              max={CUSTOM.max}
              step={CUSTOM.step}
              value={amount}
              onValueChange={slide}
              formatValue={(value) => `${formatCount(value)} credits`}
            />
          </div>

          <div className="flex flex-col gap-3 rounded-xl border border-border p-3">
            <label
              htmlFor={autoId}
              className="flex cursor-pointer items-center justify-between gap-3 text-sm"
            >
              <span>
                <span className="block font-medium">Top up on its own</span>
                <span className="block text-xs text-muted-foreground">
                  Buy this amount again when the balance runs low.
                </span>
              </span>
              <Switch id={autoId} checked={auto} onCheckedChange={setAuto} />
            </label>
            <Reveal show={auto}>
              <div className="flex flex-wrap items-center justify-between gap-2 pt-1 text-sm">
                <span className="text-muted-foreground">
                  When the balance falls under
                </span>
                <SegmentedControl
                  aria-label="Top up when the balance falls under"
                  options={THRESHOLD_OPTIONS}
                  value={threshold}
                  onValueChange={setThreshold}
                />
              </div>
            </Reveal>
          </div>

          <div className="flex items-center gap-3 rounded-xl border border-border px-3 py-2.5 text-sm">
            <CardIcon
              aria-hidden="true"
              className="size-5 shrink-0 text-chart-1"
            />
            <span className="min-w-0 flex-1 font-medium">{CARDS[card]}</span>
            <Button
              type="button"
              variant="ghost"
              size="sm"
              aria-label={`Change card, now ${CARDS[card]}`}
              onClick={() => setCard((at) => (at + 1) % CARDS.length)}
            >
              Change
            </Button>
          </div>

          <div className="flex flex-col gap-3 border-t border-border pt-4">
            <div className="flex items-baseline justify-between gap-4">
              <span className="text-sm">
                <span className="block font-medium">Total</span>
                <span className="block text-xs text-muted-foreground">
                  {formatCount(amount)} credits
                  {bonus > 0 ? ` plus ${formatCount(bonus)} bonus` : ""}, no tax
                  on credits
                </span>
              </span>
              <RollingText
                text={formatCents(price)}
                className="text-2xl font-semibold tracking-tight"
              />
            </div>
            <Button
              type="button"
              size="lg"
              aria-disabled={buying}
              onClick={buy}
            >
              {buying ? (
                <LoaderIcon
                  aria-hidden="true"
                  className="motion-safe:animate-spin"
                />
              ) : null}
              {buying
                ? "Buying credits"
                : `Buy ${formatCount(amount + bonus)} credits`}
            </Button>
            <p
              aria-live="polite"
              className="min-h-4 text-xs text-muted-foreground"
            >
              {notice}
            </p>
          </div>
        </div>
      </div>
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

