import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

/** Props for a formatted figure whose digits roll. */
export interface RollingTextProps {
  /** A figure that is already formatted, such as "$3,577" or "8.2 min". */
  text: string;
  className?: string;
}

/**
 * Shows a formatted figure and rolls each digit to its new value when the
 * text changes, as a counter does. Signs, separators and units stay still.
 * Each glyph is keyed by its place from the right, so a digit keeps its
 * column when the figure grows. It is for text that already has another
 * spoken source: the rolling columns are hidden from screen readers.
 */
export function RollingText({ text, className }: RollingTextProps) {
  const glyphs = [...text];
  return (
    <span className={cn("inline-flex tabular-nums", className)}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline-flex">
        {glyphs.map((glyph, index) => {
          const place = glyphs.length - 1 - index;
          return glyph >= "0" && glyph <= "9" ? (
            <NumberTicker key={place} value={Number(glyph)} />
          ) : (
            <span key={place} className="whitespace-pre">
              {glyph}
            </span>
          );
        })}
      </span>
    </span>
  );
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

/** Credits the clinic holds now. Each text reminder spends one. */
export const START_BALANCE = 412;

/** Under this balance the card flags the account as running low. */
export const LOW_BALANCE = 500;

/** Credits spent on each of the last 14 days, oldest first. Weekends are quiet. */
export const USAGE = [
  40, 88, 95, 102, 97, 110, 45, 38, 99, 108, 92, 104, 96, 52,
];

/** The price of one credit bought outside a pack. */
export const CREDIT_PRICE = 0.02;

/** A preset pack of credits. */
export interface Pack {
  id: string;
  credits: number;
  bonus: number;
  price: number;
}

/** The three packs, smallest first. Larger packs add bonus credits. */
export const PACKS: Pack[] = [
  { id: "small", credits: 1_000, bonus: 0, price: 20 },
  { id: "medium", credits: 5_000, bonus: 500, price: 90 },
  { id: "large", credits: 12_000, bonus: 2_000, price: 200 },
];

/** The custom amount slider's range and step, in credits. */
export const CUSTOM = { min: 500, max: 20_000, step: 500 };

/** Balances that trigger an automatic top-up. */
export const THRESHOLDS = ["100", "250", "500"] as const;

/** One threshold value as text, which the threshold control uses as its option value. */
export type Threshold = (typeof THRESHOLDS)[number];

/** The saved cards, as placeholder endings only. Change moves to the next one. */
export const CARDS = ["Visa ending 4242", "Card ending 8810"];

/** Average credits a day over the last seven days. */
export const dailyRate = () =>
  USAGE.slice(-7).reduce((sum, day) => sum + day, 0) / 7;

"use client";

import {
  animate,
  AnimatePresence,
  motion,
  useMotionValue,
  useReducedMotion,
  useTransform,
  type MotionStyle,
  type Transition,
} from "motion/react";
import { useEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

import { formatCount } from "../shared/money";

// Each column stacks the ten digits four times, so a digit can take up to three laps before it lands.
const STACKS = 4;
const ROWS = Array.from({ length: STACKS * 10 }, (_, row) => row % 10);
const ROLL_EASE = [0.165, 0.84, 0.44, 1] as const;
const WIDEN: Transition = {
  type: "spring",
  stiffness: 500,
  damping: 50,
  mass: 1,
};
const INSTANT: Transition = { duration: 0 };

/** One digit column. `roll` changes once per new value; `laps` is how many full turns it adds. */
function OdometerDigit({
  digit,
  roll,
  laps,
}: {
  digit: number;
  roll: number;
  laps: number;
}) {
  const reduceMotion = useReducedMotion();
  const position = useMotionValue(digit);
  const y = useTransform(
    position,
    (value) => `${(-value / ROWS.length) * 100}%`,
  );
  const first = useRef(true);

  useEffect(() => {
    if (first.current) {
      first.current = false;
      return;
    }
    // A roll that was cut short restarts from the digit it shows, inside the first stack.
    const from = position.get() % 10;
    position.set(from);
    const forward = (digit - Math.round(from) + 10) % 10;
    const distance = forward + 10 * laps;
    if (reduceMotion || distance === 0) {
      position.set(digit);
      return;
    }
    const controls = animate(position, from + distance, {
      duration: 0.7 + laps * 0.25,
      ease: ROLL_EASE,
      onComplete: () => position.set(digit),
    });
    return () => controls.stop();
  }, [digit, roll, laps, position, reduceMotion]);

  return (
    <span className="relative inline-block overflow-hidden">
      <span className="invisible">0</span>
      <motion.span
        // SAFETY: the style holds one CSS custom property driven by a motion value, which MotionStyle does not list.
        style={{ "--roll": y } as MotionStyle}
        className="absolute inset-x-0 top-0 flex translate-y-(--roll) flex-col items-center"
      >
        {ROWS.map((row, index) => (
          <span key={index}>{row}</span>
        ))}
      </motion.span>
    </span>
  );
}

/** Props for a balance that rolls like an odometer. */
export interface OdometerProps {
  value: number;
  className?: string;
}

/**
 * A whole number whose digits roll one way to the new value, with the lower
 * places taking extra laps, as a mechanical counter does. New leading places
 * open their width without a bounce. Screen readers read the plain number.
 */
export function Odometer({ value, className }: OdometerProps) {
  const reduceMotion = useReducedMotion();
  const text = formatCount(value);
  const glyphs = [...text].map((char, index, all) => ({
    char,
    place: all.length - 1 - index,
  }));
  // Each new value is one roll. Digits that keep their figure still turn when they sit low enough to lap.
  const [track, setTrack] = useState({ value, roll: 0, rising: false });
  if (track.value !== value)
    setTrack({ value, roll: track.roll + 1, rising: value > track.value });
  let digitPlace = -1;

  return (
    <span className={cn("inline-flex tabular-nums", className)}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline-flex">
        <AnimatePresence initial={false}>
          {glyphs
            .slice()
            .reverse()
            .map((glyph) => {
              const isDigit = glyph.char >= "0" && glyph.char <= "9";
              if (isDigit) digitPlace += 1;
              const laps = track.rising ? Math.max(0, 2 - digitPlace) : 0;
              return (
                <motion.span
                  key={glyph.place}
                  initial={{ width: 0, opacity: 0 }}
                  animate={{ width: "auto", opacity: 1 }}
                  exit={{ width: 0, opacity: 0 }}
                  transition={reduceMotion ? INSTANT : WIDEN}
                  className="inline-flex overflow-hidden"
                >
                  {isDigit ? (
                    <OdometerDigit
                      digit={Number(glyph.char)}
                      roll={track.roll}
                      laps={laps}
                    />
                  ) : (
                    <span className="whitespace-pre">{glyph.char}</span>
                  )}
                </motion.span>
              );
            })
            .reverse()}
        </AnimatePresence>
      </span>
    </span>
  );
}

const CENTS = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
});
const DOLLARS = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
  maximumFractionDigits: 0,
});
const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });

/** Rounds an amount to whole cents, so every line of a sum adds up to the shown total. */
export const toCents = (value: number) => Math.round(value * 100) / 100;

/** A dollar amount with cents, such as $1,843.20. */
export const formatCents = (value: number) => CENTS.format(toCents(value));

/** A dollar amount with no cents, such as $240. */
export const formatDollars = (value: number) =>
  DOLLARS.format(Math.round(value));

/** A whole number with thousands separators, such as 12,000. */
export const formatCount = (value: number) => WHOLE.format(Math.round(value));

/** A price that may need cents: $24 stays whole, $19.20 keeps its cents. */
export const formatPrice = (value: number) =>
  Number.isInteger(toCents(value)) ? formatDollars(value) : formatCents(value);

/** Writes a count with its noun, such as "1 seat" or "12 seats". */
export const plural = (count: number, one: string, many = `${one}s`) =>
  `${formatCount(count)} ${count === 1 ? one : many}`;

"use client";

import { useId } from "react";

import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { cn } from "@/lib/utils";

import { formatCount, formatDollars } from "../shared/money";
import { PACKS } from "./data";

/** Props for the credit pack picker. `value` is a pack id, or null for a custom amount. */
export interface PackPickerProps {
  value: string | null;
  onValueChange: (id: string) => void;
  name: string;
}

/**
 * Three preset credit packs with their price and any bonus. They form a radio
 * group, so the arrow keys move between packs and select as they go.
 */
export function PackPicker({ value, onValueChange, name }: PackPickerProps) {
  const labelId = useId();
  return (
    <div className="flex flex-col gap-2">
      <p id={labelId} className="text-sm font-medium">
        Choose a pack
      </p>
      <RadioGroup aria-labelledby={labelId} name={name} value={value ?? ""} onValueChange={onValueChange} className="@md:grid-cols-3">
      {PACKS.map((pack) => {
        const checked = pack.id === value;
        return (
          <label
            key={pack.id}
            className={cn(
              "relative isolate flex cursor-pointer flex-col gap-1 rounded-xl border p-3 text-sm",
              "has-focus-visible:ring-2 has-focus-visible:ring-ring has-focus-visible:ring-offset-2 has-focus-visible:ring-offset-card",
              checked
                ? "border-chart-1"
                : "border-border hover:border-muted-foreground/40",
            )}
          >
            <span
              aria-hidden="true"
              className={cn(
                "absolute inset-0 -z-10 rounded-xl",
                checked && "bg-chart-1/10",
              )}
            />
            <RadioGroupItem value={pack.id} aria-label={`${formatCount(pack.credits)} credits`} className="sr-only" />
            <span className="flex flex-col items-start gap-1">
              <span className="font-semibold tabular-nums">
                {formatCount(pack.credits)} credits
              </span>
              {pack.bonus > 0 ? (
                <span className="rounded-full bg-marketing-green-surface px-2 py-0.5 text-xs font-medium text-marketing-green-ink">
                  +{formatCount(pack.bonus)} bonus
                </span>
              ) : null}
            </span>
            <span className="text-muted-foreground tabular-nums">
              {formatDollars(pack.price)}
            </span>
          </label>
        );
      })}
      </RadioGroup>
    </div>
  );
}

"use client";

import type { CSSProperties } from "react";
