"use client";

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type Transition,
} from "motion/react";
import type { ReactNode } from "react";

// Critically damped, so a line opens and settles without a bounce.
const HEIGHT: Transition = {
  type: "spring",
  stiffness: 420,
  damping: 42,
  mass: 1,
};
const INSTANT: Transition = { duration: 0 };

/** Props for content that opens and closes its height. */
export interface RevealProps {
  show: boolean;
  children: ReactNode;
  className?: string;
}

/**
 * Opens its content from zero height with a fade and closes it the same way,
 * so the lines under it glide instead of jumping. Reduced motion shows and
 * hides it at once.
 */
export function Reveal({ show, children, className }: RevealProps) {
  const reduceMotion = useReducedMotion();
  const transition = reduceMotion ? INSTANT : HEIGHT;
  return (
    <AnimatePresence initial={false}>
      {show ? (
        <motion.div
          initial={{ height: 0, opacity: 0 }}
          animate={{ height: "auto", opacity: 1 }}
          exit={{ height: 0, opacity: 0 }}
          transition={transition}
          className="overflow-hidden"
        >
          <div className={className}>{children}</div>
        </motion.div>
      ) : null}
    </AnimatePresence>
  );
}
